//! Expected values are explicit, not snapshots generated by the implementation.
//! These tests use the NODES policies documented in docs/DATA_TREE_ENGINE.md.
use morphlet::data_tree as dt;
use morphlet::data_tree::{ItemMatches, MATCH_PARAM, MatchMode, PORT_PREFIX, Slot};
use morphlet::engine::Evaluator;
use morphlet::model::{Graph, MAX_ITEMS, NodeKind, Tree, Value};
use morphlet::persistence::{self, History, Project};

fn numbers(branches: &[(&[u32], &[f64])]) -> Tree {
    Tree {
        branches: branches
            .iter()
            .map(|(path, values)| {
                (
                    path.to_vec(),
                    values.iter().map(|v| Value::Number(*v)).collect(),
                )
            })
            .collect(),
    }
}
fn n(values: &[f64]) -> Vec<Value> {
    values.iter().copied().map(Value::Number).collect()
}
fn tuples(lists: &[&[Value]], mode: MatchMode) -> Vec<Vec<f64>> {
    ItemMatches::new(lists, mode, MAX_ITEMS)
        .unwrap()
        .map(|r| r.into_iter().map(|v| v.number().unwrap()).collect())
        .collect()
}
fn eval(graph: &Graph, id: u64) -> Tree {
    Evaluator::default()
        .evaluate(graph, &|| false)
        .outputs
        .remove(&id)
        .unwrap()
        .unwrap()
}

#[test]
fn flat_graft_partition_and_roundtrip_preserve_order_and_empty() {
    let t = numbers(&[(&[0], &[1., 2.]), (&[1], &[]), (&[2], &[3.])]);
    assert_eq!(dt::flatten(&t).unwrap(), numbers(&[(&[0], &[1., 2., 3.])]));
    assert_eq!(
        dt::graft(&t).unwrap(),
        numbers(&[
            (&[0, 0], &[1.]),
            (&[0, 1], &[2.]),
            (&[1], &[]),
            (&[2, 0], &[3.])
        ])
    );
    assert_eq!(dt::unflatten(&dt::flatten(&t).unwrap(), &t).unwrap(), t);
    assert_eq!(dt::partition(&t, 1).unwrap(), dt::graft(&t).unwrap());
    assert!(dt::unflatten(&Tree::default(), &t).is_err());
}
#[test]
fn mixed_depth_graft_collisions_do_not_lose_items() {
    let t = numbers(&[(&[0], &[1.]), (&[0, 0], &[])]);
    assert_eq!(dt::graft(&t).unwrap(), numbers(&[(&[0, 0], &[1.])]));
    let deep = numbers(&[(&[0; 32], &[1.])]);
    assert!(dt::graft(&deep).is_err());
}
#[test]
fn hierarchical_simplify_trim_mapper_and_merge() {
    let t = numbers(&[(&[0, 0], &[1.]), (&[0, 1], &[2.]), (&[1, 0], &[3.])]);
    assert_eq!(
        dt::path_mapper(&t, "{A;B}->{B;A}").unwrap(),
        numbers(&[(&[0, 0], &[1.]), (&[0, 1], &[3.]), (&[1, 0], &[2.])])
    );
    assert_eq!(
        dt::trim(&t, 1).unwrap(),
        numbers(&[(&[0], &[1., 2.]), (&[1], &[3.])])
    );
    let constant = numbers(&[(&[4, 0, 9], &[1.]), (&[4, 2, 9], &[2.])]);
    assert_eq!(
        dt::simplify(&constant).unwrap(),
        numbers(&[(&[0], &[1.]), (&[2], &[2.])])
    );
    assert_eq!(
        dt::path_mapper(&t, "{A;B}->{A}").unwrap(),
        dt::trim(&t, 1).unwrap()
    );
    assert_eq!(
        dt::merge(&[t.clone(), t.clone()]).unwrap(),
        numbers(&[
            (&[0, 0], &[1., 1.]),
            (&[0, 1], &[2., 2.]),
            (&[1, 0], &[3., 3.])
        ])
    );
    for invalid in [
        "{A;B}->{C}",
        "{A;B}->{A+1}",
        "print(1)",
        "{A}->{-1}",
        "{A}->{2147483648}",
    ] {
        assert!(dt::path_mapper(&t, invalid).is_err(), "{invalid}");
    }
}
#[test]
fn shortest_longest_cross_and_empty() {
    let a = n(&[1., 2., 3.]);
    let b = n(&[10., 20.]);
    assert_eq!(
        tuples(&[&a, &b], MatchMode::Shortest),
        vec![vec![1., 10.], vec![2., 20.]]
    );
    assert_eq!(
        tuples(&[&a, &b], MatchMode::Longest),
        vec![vec![1., 10.], vec![2., 20.], vec![3., 20.]]
    );
    assert_eq!(
        tuples(&[&a, &b], MatchMode::Cross),
        vec![
            vec![1., 10.],
            vec![1., 20.],
            vec![2., 10.],
            vec![2., 20.],
            vec![3., 10.],
            vec![3., 20.]
        ]
    );
    for mode in [MatchMode::Shortest, MatchMode::Longest, MatchMode::Cross] {
        assert!(tuples(&[&a, &[]], mode).is_empty());
    }
}
#[test]
fn ordinal_branches_repeat_last_not_union() {
    let a = numbers(&[(&[0, 0], &[1., 2.]), (&[0, 1], &[]), (&[1, 0], &[3.])]);
    let b = numbers(&[(&[8], &[10.]), (&[9], &[20.])]);
    let trees = [a, b];
    let m = dt::match_branches(&trees).unwrap();
    assert_eq!(
        m.iter().map(|x| x.path.clone()).collect::<Vec<_>>(),
        vec![vec![0, 0], vec![0, 1], vec![1, 0]]
    );
    assert_eq!(m[0].lists[1], &n(&[10.]));
    assert!(m[1].lists[0].is_empty());
    assert_eq!(m[2].lists[1], &n(&[20.]));
    assert_eq!(
        dt::cross_reference(&trees).unwrap(),
        vec![
            numbers(&[(&[0, 0], &[1., 2.]), (&[0, 1], &[]), (&[1, 0], &[3.])]),
            numbers(&[(&[0, 0], &[10., 10.]), (&[0, 1], &[]), (&[1, 0], &[20.])])
        ]
    );
}
#[test]
fn matrix_flip_and_missing_slot() {
    let t = numbers(&[(&[3, 0], &[1., 2., 3.]), (&[3, 1], &[4., 5., 6.])]);
    assert_eq!(
        dt::flip_matrix(&t).unwrap(),
        numbers(&[
            (&[3, 0], &[1., 4.]),
            (&[3, 1], &[2., 5.]),
            (&[3, 2], &[3., 6.])
        ])
    );
    assert_eq!(dt::flip_matrix(&dt::flip_matrix(&t).unwrap()).unwrap(), t);
    assert!(dt::flip_matrix(&numbers(&[(&[0], &[1.]), (&[1], &[])])).is_err());
    assert!(dt::item(&t, &[3, 0], 3).is_none());
    // Slot is a public future-port type, not yet a runtime Value variant.
    let slots = [Slot::Item(1), Slot::Null, Slot::Missing];
    assert_ne!(slots[1], slots[2]);
}
#[test]
fn cross_budget_before_iteration_and_10000_items() {
    let a = vec![Value::Number(0.); 128];
    let b = vec![Value::Number(1.); 128];
    let lists = [a.as_slice(), b.as_slice()];
    let m = ItemMatches::new(&lists, MatchMode::Cross, MAX_ITEMS).unwrap();
    assert_eq!(m.cardinality(), 16384);
    assert!(ItemMatches::new(&lists, MatchMode::Cross, 100).is_err());
    let huge = vec![Value::Number(1.); MAX_ITEMS];
    assert!(ItemMatches::new(&[&huge, &huge], MatchMode::Cross, MAX_ITEMS).is_err());
    let t = Tree {
        branches: [(vec![0], vec![Value::Number(2.); 10_001])].into(),
    };
    assert_eq!(dt::flatten(&t).unwrap().item_count(), 10_001);
    assert_eq!(dt::graft(&t).unwrap().branches.len(), 10_001);
}
#[test]
fn graph_math_and_geometry_share_matching() {
    let mut graph = Graph::default();
    let a = graph.add(NodeKind::Series, [0., 0.]).unwrap();
    let b = graph.add(NodeKind::Series, [0., 0.]).unwrap();
    let add = graph.add(NodeKind::Add, [0., 0.]).unwrap();
    let point = graph.add(NodeKind::Point, [0., 0.]).unwrap();
    graph.node_mut(a).unwrap().params.extend([
        ("start".into(), 1.),
        ("step".into(), 1.),
        ("count".into(), 3.),
    ]);
    graph.node_mut(b).unwrap().params.extend([
        ("start".into(), 10.),
        ("step".into(), 10.),
        ("count".into(), 2.),
    ]);
    graph.connect(a, add, "a").unwrap();
    graph.connect(b, add, "b").unwrap();
    graph.connect(a, point, "x").unwrap();
    graph.connect(b, point, "y").unwrap();
    graph
        .node_mut(add)
        .unwrap()
        .params
        .insert(MATCH_PARAM.into(), 1.);
    assert_eq!(eval(&graph, add), numbers(&[(&[0], &[11., 22.])]));
    graph
        .node_mut(add)
        .unwrap()
        .params
        .insert(MATCH_PARAM.into(), 0.);
    assert_eq!(eval(&graph, add), numbers(&[(&[0], &[11., 22., 23.])]));
    graph
        .node_mut(add)
        .unwrap()
        .params
        .insert(MATCH_PARAM.into(), 2.);
    graph
        .node_mut(point)
        .unwrap()
        .params
        .insert(MATCH_PARAM.into(), 2.);
    assert_eq!(
        eval(&graph, add),
        numbers(&[(&[0], &[11., 21., 12., 22., 13., 23.])])
    );
    let p = eval(&graph, point);
    assert_eq!(p.branches[&vec![0]].len(), 6);
    assert_eq!(p.branches[&vec![0]][1], Value::Point([1., 20., 0.]));
}
#[test]
fn graph_large_repeat_partition_save_load_and_undo_redo() {
    let mut graph = Graph::default();
    let s = graph.add(NodeKind::Number, [0., 0.]).unwrap();
    let r = graph.add(NodeKind::RepeatData, [0., 0.]).unwrap();
    let p = graph.add(NodeKind::PartitionList, [0., 0.]).unwrap();
    let g = graph.add(NodeKind::SimplifyTree, [0., 0.]).unwrap();
    graph.connect(s, r, "list").unwrap();
    graph.connect(r, p, "tree").unwrap();
    graph.connect(p, g, "tree").unwrap();
    graph
        .node_mut(r)
        .unwrap()
        .params
        .insert("count".into(), 10_001.);
    graph
        .node_mut(p)
        .unwrap()
        .params
        .insert("size".into(), 1000.);
    graph
        .node_mut(g)
        .unwrap()
        .params
        .insert(format!("{PORT_PREFIX}tree"), 3.);
    let mut project = Project::new("tree test", graph);
    let mut history = History::default();
    history.checkpoint(&project);
    let original = eval(&project.graph, p);
    assert_eq!(original.item_count(), 10_001);
    assert_eq!(original.branches.len(), 11);
    assert_eq!(original.branches[&vec![0, 10]].len(), 1);
    let simplified = eval(&project.graph, g);
    assert_eq!(simplified.branches[&vec![10]].len(), 1);
    let mut evaluator = Evaluator::default();
    let first = evaluator.evaluate(&project.graph, &|| false);
    assert_eq!(first.outputs[&p].as_ref().unwrap(), &original);
    project
        .graph
        .node_mut(r)
        .unwrap()
        .params
        .insert("count".into(), 2.);
    let second = evaluator.evaluate(&project.graph, &|| false);
    assert_eq!(second.outputs[&p].as_ref().unwrap().item_count(), 2);
    assert!(history.undo(&mut project));
    assert_eq!(
        evaluator.evaluate(&project.graph, &|| false).outputs[&p]
            .as_ref()
            .unwrap(),
        &original
    );
    assert!(history.redo(&mut project));
    assert_eq!(
        evaluator.evaluate(&project.graph, &|| false).outputs[&p]
            .as_ref()
            .unwrap()
            .item_count(),
        2
    );
    let path = std::env::temp_dir().join(format!(
        "nodes-tree-{}-{}.morph",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    persistence::save(&path, &project).unwrap();
    let loaded = persistence::load(&path).unwrap();
    let _ = std::fs::remove_file(&path);
    assert_eq!(loaded.graph, project.graph);
    assert_eq!(eval(&loaded.graph, p), eval(&project.graph, p));
}
#[test]
fn path_mapper_cache_key_tracks_rule_edits_and_port_transforms() {
    let mut g = Graph::default();
    let s = g.add(NodeKind::Series, [0., 0.]).unwrap();
    let m = g.add(NodeKind::PathMapper, [0., 0.]).unwrap();
    g.node_mut(s).unwrap().params.insert("count".into(), 2.);
    g.connect(s, m, "tree").unwrap();
    g.node_mut(m)
        .unwrap()
        .params
        .insert(format!("{PORT_PREFIX}tree"), 2.);
    let mut e = Evaluator::default();
    let first = e.evaluate(&g, &|| false);
    assert!(
        first.outputs[&m]
            .as_ref()
            .unwrap()
            .branches
            .contains_key(&vec![1, 0])
    );
    g.node_mut(m).unwrap().script = "{A;B}->{B;A;7}".into();
    let second = e.evaluate(&g, &|| false);
    assert!(
        second.outputs[&m]
            .as_ref()
            .unwrap()
            .branches
            .contains_key(&vec![1, 0, 7])
    );
    assert_eq!(second.cached, 1);
}
